<?php
declare(strict_types=1);

function i18n_languages(): array
{
    return [
        'en' => 'English',
        'fr' => 'Fran' . "\u{00E7}" . 'ais',
        'sw' => 'Kiswahili',
    ];
}

function i18n_language(): string
{
    $supported = i18n_languages();
    $requested = $_GET['lang'] ?? null;
    if (is_string($requested) && isset($supported[$requested])) {
        $_SESSION['language'] = $requested;
    }
    $language = $_SESSION['language'] ?? 'en';
    return isset($supported[$language]) ? $language : 'en';
}

function render_language_switcher(): string
{
    $language = i18n_language();
    $requestPath = parse_url($_SERVER['REQUEST_URI'] ?? '/', PHP_URL_PATH) ?: '/';
    $action = htmlspecialchars($requestPath, ENT_QUOTES, 'UTF-8');
    $hiddenInputs = '';
    foreach ($_GET as $key => $value) {
        if ($key === 'lang' || !is_scalar($value)) {
            continue;
        }
        $hiddenInputs .= '<input type="hidden" name="' . htmlspecialchars((string) $key, ENT_QUOTES, 'UTF-8')
            . '" value="' . htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8') . '">';
    }
    $options = '';
    foreach (i18n_languages() as $code => $name) {
        $selected = $code === $language ? ' selected' : '';
        $options .= '<option value="' . htmlspecialchars($code, ENT_QUOTES, 'UTF-8') . '"' . $selected . '>'
            . htmlspecialchars($name, ENT_QUOTES, 'UTF-8') . '</option>';
    }

    return '<form class="language-form" method="get" action="' . $action . '">' . $hiddenInputs
        . '<label class="language-picker"><span class="visually-hidden">Language</span>'
        . '<select class="form-select form-select-sm" name="lang" aria-label="Language" onchange="this.form.submit()">'
        . $options . '</select></label><noscript><button class="btn btn-sm btn-outline-secondary" type="submit">Apply</button></noscript></form>';
}

