function i18n_translate_text(string $text, string $language): string
{
    if ($language === 'en' || trim($text) === '') {
        return $text;
    }
    static $catalogs = [];
    if (!isset($catalogs[$language])) {
        $dictionary = array_merge(i18n_dictionary(), i18n_extra_dictionary());
        $lookup = [];
        foreach ($dictionary as $phrase => $translations) {
            if (isset($translations[$language])) {
                $lookup[strtolower($phrase)] = $translations[$language];
            }
        }
        $phrases = array_keys($lookup);
        usort($phrases, static fn(string $a, string $b): int => strlen($b) <=> strlen($a));
        $patternParts = [];
        foreach ($phrases as $phrase) {
            $part = preg_quote($phrase, '~');
            if (preg_match('/^[\p{L}\p{N}_]/u', $phrase) === 1) {
                $part = '(?<![\p{L}\p{N}_])' . $part;
            }
            if (preg_match('/[\p{L}\p{N}_]$/u', $phrase) === 1) {
                $part .= '(?![\p{L}\p{N}_])';
            }
            $patternParts[] = $part;
        }
        $patterns = [];
        foreach (array_chunk($patternParts, 50) as $parts) {
            $patterns[] = '~(?:' . implode('|', $parts) . ')~iu';
        }
        $catalogs[$language] = [$dictionary, $lookup, $patterns];
    }
    [$dictionary, $lookup, $patterns] = $catalogs[$language];
    $trimmed = trim(html_entity_decode($text, ENT_QUOTES | ENT_HTML5, 'UTF-8'));
    if (isset($dictionary[$trimmed][$language])) {
        $translated = $dictionary[$trimmed][$language];
        $leading = substr($text, 0, strlen($text) - strlen(ltrim($text)));
        $trailing = substr($text, strlen(rtrim($text)));
        return $leading . htmlspecialchars($translated, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8') . $trailing;
    }

    // Translate known interface phrases inside mixed UI labels while leaving unknown text untouched.
    $candidates = [];
    foreach ($patterns as $pattern) {
        if (preg_match_all($pattern, $text, $found, PREG_OFFSET_CAPTURE) === false) {
            continue;
        }
        foreach ($found[0] as [$matched, $offset]) {
            $key = strtolower($matched);
            if (isset($lookup[$key])) {
                $candidates[] = [
                    'offset' => $offset,
                    'matched' => $matched,
                    'replacement' => $lookup[$key],
                ];
            }
        }
    }
    if ($candidates === []) {
        return $text;
    }
    usort($candidates, static fn(array $a, array $b): int => $a['offset'] <=> $b['offset'] ?: strlen($b['matched']) <=> strlen($a['matched']));
    $translated = '';
    $cursor = 0;
    foreach ($candidates as $candidate) {
        $offset = $candidate['offset'];
        if ($offset < $cursor) {
            continue;
        }
        $translated .= substr($text, $cursor, $offset - $cursor) . $candidate['replacement'];
        $cursor = $offset + strlen($candidate['matched']);
    }
    return $translated . substr($text, $cursor);
}

function i18n_translate_output(string $html): string
{
    $language = i18n_language();
    if ($language === 'en') {
        return $html;
    }
    $html = str_replace('<html lang="en">', '<html lang="' . $language . '">', $html);
    $html = preg_replace_callback('/>([^<>]+)</u', static function (array $match) use ($language): string {
        return '>' . i18n_translate_text($match[1], $language) . '<';
    }, $html) ?? $html;
    $html = preg_replace_callback('/\b(placeholder|title|aria-label|alt)=(["\'])(.*?)\2/su', static function (array $match) use ($language): string {
        return $match[1] . '=' . $match[2] . i18n_translate_text($match[3], $language) . $match[2];
    }, $html) ?? $html;
    return $html;
}
